# Baseline + applicable, visible context factors. Final scores are bounded to 0–100.
def risk_score(finding):
    factors = [{"label": "Severity baseline", "value": {"CRITICAL": 55, "HIGH": 59, "MEDIUM": 33, "LOW": 13}[finding["severity"]]}, {"label": "Internet-facing exposure", "value": 8}, {"label": "High business criticality", "value": 5}, {"label": "Confidence adjustment", "value": 5 if finding["confidence"] >= 95 else 2}]
    if finding["id"] == "CG-F002": factors[0]["value"] = 57
    if finding["id"] == "CG-F003": factors[0]["value"] = 60
    if finding["id"] == "CG-F004": factors[0]["value"] = 63
    if finding["id"] == "CG-F001": factors.append({"label": "Credential exposure", "value": 15})
    if finding["path"]: factors.append({"label": "Attack path participation", "value": 8})
    if finding["related"]: factors.append({"label": "Related finding correlation", "value": 3 if finding["severity"] == "HIGH" else 0})
    return min(100, sum(f["value"] for f in factors)), [f for f in factors if f["value"]]

def make_finding(n, title, severity, cwe, confidence, category, resource, description, evidence, technical, business, remediation, related=None, path=None, cvss=0, status="OPEN"):
    f = dict(id=f"CG-F{n:03d}", title=title, severity=severity, cwe=cwe, confidence=confidence, category=category, resource=resource, description=description, evidence=evidence, technical_impact=technical, business_impact=business, remediation=remediation, related=related or [], path=path, cvss=cvss, status=status, asset=ASSET["name"], first_detected="2026-08-20T09:00:00Z", last_detected="2026-09-10T09:00:00Z")
    f["risk"], f["factors"] = risk_score(f)
    f["priority"] = "P1 · Immediate" if f["risk"] >= 90 else "P2 · Within 7 days" if f["risk"] >= 75 else "P3 · Within 30 days" if f["risk"] >= 40 else "P4 · Next maintenance"
    return f

