def analysis(f, asset=ASSET):
    correlation = "It participates in a potential exposure chain; fixing it also interrupts related risk." if f["path"] else "Treat this as a defense-in-depth issue in the context of the related application controls."
    return [{"title": "Why This Matters", "body": f"This {f['severity'].lower()} {f['category'].lower()} finding has contextual risk {f['risk']}/100 and {f['confidence']}% fixture confidence. The {asset['exposure'].lower()}, {asset['criticality'].lower()}-criticality asset increases its priority. {correlation}"}, {"title": "Technical Impact", "body": f["technical_impact"]}, {"title": "Business Impact", "body": f["business_impact"]}, {"title": "Recommended Action", "body": f["remediation"][0]}, {"title": "Remediation Priority", "body": f["priority"] + ". Validate the change in a subsequent assessment; a new simulated scan alone does not constitute remediation."}, {"title": "Related Risk", "body": ("Review " + ", ".join(f["related"]) + ". " if f["related"] else "No direct correlated finding in this dataset. ") + correlation}]

QUESTIONS = ["What should we fix first?", "Explain our biggest risk.", "Summarize the current security posture.", "What is the top potential attack path?", "Create a remediation plan.", "Explain these findings to management."]

def analyst(question, findings, score, paths):
    opened = sorted([f for f in findings if f["status"] == "OPEN"], key=lambda f: -f["risk"])
    if not opened: return {"title": "No open findings", "intro": "All findings have a disposition. Verify remediation independently before treating accepted or false-positive findings as fixed.", "sections": []}
    top = opened[0]
    priorities = [{"title": f"{i+1:02d} · {f['title']}", "body": f"{f['priority']} · Risk {f['risk']}/100. {f['remediation'][0]} {('Interrupts ' + f['path'] + '.') if f['path'] else 'Strengthens the application security baseline.'}"} for i, f in enumerate(opened[:5])]
    if question in (QUESTIONS[0], QUESTIONS[4]):
        return {"title": "Your prioritized remediation plan", "intro": f"Start with {top['title'].lower()}. Priorities combine severity, exposure, business criticality, confidence and correlation; they are not simply a list of scanner alerts.", "sections": priorities}
    if question == QUESTIONS[1]: return {"title": "The highest-priority exposure", "intro": top["title"], "sections": analysis(top)}
    if question == QUESTIONS[3]:
        path = paths[0] if paths else None
        return {"title": "The leading potential attack path", "intro": path["explanation"] if path else "No active path is supported by the current open findings.", "sections": [{"title": "Possible exposure chain", "body": " → ".join(path["nodes"])}, {"title": "Recommended fix order", "body": " → ".join(path["fix_order"])}] if path else []}
    return {"title": "Security posture, explained clearly", "intro": f"FinTrust's latest completed assessment has a benchmark score of {score}/100. There are {len(opened)} open findings, including {sum(f['severity']=='CRITICAL' for f in opened)} critical. The latest score describes the assessment snapshot, while dispositions reflect the current triage state.", "sections": [{"title": "Business exposure", "body": top["business_impact"]}, {"title": "Progress and next steps", "body": "The seeded benchmark improved from 51 to 58 as security controls matured. Prioritize credential handling, public build artifacts and browser/session controls; assign the Digital Banking Team to verify each fix."}, {"title": "Decision for management", "body": "Schedule immediate containment of the highest-risk exposure and a seven-day hardening sprint. Track verified remediation separately from accepted risk. These results are simulated and are not evidence of a real compromise."}]}
